#include <iostream>
#include <iomanip>

int main() {
    // Modern C++17: Strong typing, explicit constants, and deterministic formatted output
    constexpr double pi = 3.141592653589793;
    double radius = 0.0;

    if (std::cin >> radius) {
        const double area = radius * radius * pi;
        std::cout << "Radius: " << std::fixed << std::setprecision(2) << radius << "\n";
        std::cout << "Area: " << std::fixed << std::setprecision(4) << area << "\n";
    }
    return 0;
}

#include <iostream>
#include <string>

int main() {
    // Simulating how compiled C++ receives arguments via stdin and standard I/O managed by the OS
    std::string language;
    std::string translation_type;

    if (std::cin >> language >> translation_type) {
        std::cout << "Language: " << language << "\n";
        std::cout << "Type: " << translation_type << "\n";
        if (translation_type == "Compiled") {
            std::cout << "Execution: Translated entirely to machine code before execution.\n";
        } else {
            std::cout << "Execution: Translated statement-by-statement at runtime.\n";
        }
    }
    return 0;
}
